-- Plan « Base aérobie, FTP & aéro » : toutes les récupérations des
-- fractionnés en position aéro (position_recup = prolongateurs), minutes en
-- aéro recalculées, objectifs mis à jour, commentaire live à la 1re
-- récupération et explication dans les descriptions (séances et plan) :
-- récupérer en aéro apprend au cerveau à associer la position au repos.

UPDATE public.training_sessions
SET session_json = jsonb_set(session_json, '{blocks}', '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 90.0, "power_end": 55.0, "duration_work": 480, "duration_recup": 240, "repetitions": 3, "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 600, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb),
    aero_duration_sec = 1320,
    live_comments = '[{"at": 1080, "key": "base_ftp_aero_4w_lc_recup", "duration": 15}, {"at": 2750, "key": "base_ftp_aero_4w_lc_start", "duration": 12}]'::jsonb
WHERE name = 'base_ftp_aero_4w_w1s1_name';

