UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Blocs au seuil en position libre, récupération facile entre chaque. On termine par un bloc à 70 % FTP en position aéro : c''est là que tu apprends à rester bas quand les jambes sont lourdes. Toutes les récupérations se font en position aéro : récupérer en aéro apprend à ton cerveau à l''associer au repos (même si, physiquement, ce n''en est pas tout à fait un).", "en": "Threshold blocks in any position, easy recovery between them. We finish with a block at 70% FTP in the aero position: that''s where you learn to stay low on tired legs. Every recovery is done in the aero position: recovering in aero teaches your brain to link it with rest (even though, physically, it isn''t quite rest).", "es": "Bloques de umbral en posición libre, recuperación suave entre ellos. Terminamos con un bloque al 70 % FTP en posición aero: ahí aprendes a seguir abajo con las piernas cansadas. Todas las recuperaciones se hacen en posición aero: recuperar en aero enseña a tu cerebro a asociarla con el descanso (aunque, físicamente, no lo sea del todo).", "it": "Blocchi alla soglia in posizione libera, recupero facile tra un blocco e l''altro. Si chiude con un blocco al 70 % FTP in posizione aero: è lì che impari a restare basso con le gambe stanche. Tutti i recuperi si fanno in posizione aero: recuperare in aero insegna al tuo cervello ad associarla al riposo (anche se, fisicamente, non lo è del tutto).", "de": "Schwellenblöcke in freier Position, lockere Erholung dazwischen. Zum Schluss ein Block bei 70 % FTP in Aeroposition: Hier lernst du, mit müden Beinen tief zu bleiben. Jede Erholung erfolgt in Aeroposition: So lernt dein Gehirn, sie mit Ruhe zu verbinden (auch wenn sie körperlich keine echte Pause ist).", "nl": "Drempelblokken in vrije houding, rustig herstel ertussen. We sluiten af met een blok op 70 % FTP in aerohouding: daar leer je laag te blijven met vermoeide benen. Elk herstel gebeurt in aerohouding: zo leert je brein die houding te koppelen aan rust (ook al is het fysiek niet helemaal rust).", "pt": "Blocos no limiar em posição livre, recuperação leve entre eles. Terminamos com um bloco a 70 % FTP na posição aero: é aí que você aprende a ficar baixo com as pernas cansadas. Todas as recuperações são feitas na posição aero: recuperar em aero ensina seu cérebro a associá-la ao descanso (mesmo que, fisicamente, não seja bem um descanso).", "ja": "ポジション自由で閾値ブロック、間は楽に回復。最後に70 % FTPでエアロポジションのブロック。脚が重い時こそ低い姿勢を保つ練習です。 回復はすべてエアロポジションで行います。エアロで回復することで、脳がこの姿勢を休息と結びつけます（体にとっては完全な休息ではありませんが）。", "tr": "Serbest pozisyonda eşik blokları, aralarında kolay toparlanma. Aero pozisyonda %70 FTP''lik bir blokla bitiriyoruz: yorgun bacaklarla alçakta kalmayı burada öğrenirsin. Tüm toparlanmalar aero pozisyonda yapılır: aero''da toparlanmak beynine bu pozisyonu dinlenmeyle ilişkilendirmeyi öğretir (fiziksel olarak tam bir dinlenme olmasa da)."}'::jsonb,
  'objectif', replace('{"fr": "Faire monter ta FTP, puis tenir la position aéro à 70 % sous fatigue", "en": "Raise your FTP, then hold the aero position at 70% under fatigue", "es": "Subir tu FTP y luego mantener la posición aero al 70 % con fatiga", "it": "Alzare la tua FTP, poi tenere la posizione aero al 70 % sotto fatica", "de": "Deine FTP steigern und danach die Aeroposition bei 70 % unter Ermüdung halten", "nl": "Je FTP verhogen en daarna de aerohouding op 70 % vasthouden onder vermoeidheid", "pt": "Aumentar sua FTP e depois manter a posição aero a 70 % sob fadiga", "ja": "FTPを高め、疲労下で70 %のエアロポジションを維持する", "tr": "FTP''ni yükselt, ardından yorgunken %70''te aero pozisyonu koru"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w1s1_name', 'base_ftp_aero_4w_w2s1_name', 'base_ftp_aero_4w_w3s1_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "La séance clé du plan : des blocs à 70 % FTP en position aéro, de plus en plus longs d''une semaine à l''autre. L''intensité reste facile pour que toute ton attention aille à la position : tête basse, épaules relâchées, respiration calme. Entre les blocs, récupère à 60 % sans quitter la position. Toutes les récupérations se font en position aéro : récupérer en aéro apprend à ton cerveau à l''associer au repos (même si, physiquement, ce n''en est pas tout à fait un).", "en": "The key session of the plan: blocks at 70% FTP in the aero position, longer every week. The intensity stays easy so all your attention goes to the position: head low, shoulders relaxed, calm breathing. Between blocks, recover at 60% without leaving the position. Every recovery is done in the aero position: recovering in aero teaches your brain to link it with rest (even though, physically, it isn''t quite rest).", "es": "La sesión clave del plan: bloques al 70 % FTP en posición aero, más largos cada semana. La intensidad es suave para que toda tu atención vaya a la posición: cabeza baja, hombros relajados, respiración tranquila. Entre bloques, recupera al 60 % sin dejar la posición. Todas las recuperaciones se hacen en posición aero: recuperar en aero enseña a tu cerebro a asociarla con el descanso (aunque, físicamente, no lo sea del todo).", "it": "La sessione chiave del piano: blocchi al 70 % FTP in posizione aero, sempre più lunghi di settimana in settimana. L''intensità resta facile perché tutta l''attenzione vada alla posizione: testa bassa, spalle rilassate, respiro calmo. Tra i blocchi, recupera al 60 % senza lasciare la posizione. Tutti i recuperi si fanno in posizione aero: recuperare in aero insegna al tuo cervello ad associarla al riposo (anche se, fisicamente, non lo è del tutto).", "de": "Die Schlüsseleinheit des Plans: Blöcke bei 70 % FTP in Aeroposition, jede Woche länger. Die Intensität bleibt leicht, damit deine ganze Aufmerksamkeit der Position gilt: Kopf tief, Schultern locker, ruhige Atmung. Zwischen den Blöcken bei 60 % erholen, ohne die Position zu verlassen. Jede Erholung erfolgt in Aeroposition: So lernt dein Gehirn, sie mit Ruhe zu verbinden (auch wenn sie körperlich keine echte Pause ist).", "nl": "De kernsessie van het plan: blokken op 70 % FTP in aerohouding, elke week langer. De intensiteit blijft licht zodat al je aandacht naar de houding gaat: hoofd laag, schouders ontspannen, rustige ademhaling. Herstel tussen de blokken op 60 % zonder de houding te verlaten. Elk herstel gebeurt in aerohouding: zo leert je brein die houding te koppelen aan rust (ook al is het fysiek niet helemaal rust).", "pt": "A sessão-chave do plano: blocos a 70 % FTP na posição aero, mais longos a cada semana. A intensidade é leve para que toda a sua atenção vá para a posição: cabeça baixa, ombros relaxados, respiração calma. Entre os blocos, recupere a 60 % sem sair da posição. Todas as recuperações são feitas na posição aero: recuperar em aero ensina seu cérebro a associá-la ao descanso (mesmo que, fisicamente, não seja bem um descanso).", "ja": "プランの核となるセッション：70 % FTPのエアロポジションのブロックを週ごとに長くします。強度は楽なので、ポジションに集中：頭を低く、肩の力を抜き、呼吸を落ち着けて。ブロックの間は姿勢を崩さず60 %で回復します。 回復はすべてエアロポジションで行います。エアロで回復することで、脳がこの姿勢を休息と結びつけます（体にとっては完全な休息ではありませんが）。", "tr": "Planın anahtar seansı: aero pozisyonda %70 FTP''de, her hafta uzayan bloklar. Yoğunluk kolay kalır ki tüm dikkatin pozisyonda olsun: baş aşağıda, omuzlar gevşek, sakin nefes. Bloklar arasında pozisyonu bozmadan %60''ta toparlan. Tüm toparlanmalar aero pozisyonda yapılır: aero''da toparlanmak beynine bu pozisyonu dinlenmeyle ilişkilendirmeyi öğretir (fiziksel olarak tam bir dinlenme olmasa da)."}'::jsonb,
  'objectif', replace('{"fr": "Tenir la position aéro {aero} minutes à 70 % FTP", "en": "Hold the aero position for {aero} minutes at 70% FTP", "es": "Mantener la posición aero {aero} minutos al 70 % FTP", "it": "Tenere la posizione aero {aero} minuti al 70 % FTP", "de": "Die Aeroposition {aero} Minuten bei 70 % FTP halten", "nl": "De aerohouding {aero} minuten vasthouden op 70 % FTP", "pt": "Manter a posição aero {aero} minutos a 70 % FTP", "ja": "70 % FTPでエアロポジションを{aero}分維持", "tr": "%70 FTP''de aero pozisyonu {aero} dakika koru"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w1s2_name', 'base_ftp_aero_4w_w2s2_name', 'base_ftp_aero_4w_w3s2_name', 'base_ftp_aero_4w_w4s2_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Efforts courts au-dessus du seuil, position libre, récupération égale à l''effort. Un bloc à 70 % en aéro clôt la séance. Toutes les récupérations se font en position aéro : récupérer en aéro apprend à ton cerveau à l''associer au repos (même si, physiquement, ce n''en est pas tout à fait un).", "en": "Short efforts above threshold, any position, recovery as long as the effort. A block at 70% in the aero position closes the session. Every recovery is done in the aero position: recovering in aero teaches your brain to link it with rest (even though, physically, it isn''t quite rest).", "es": "Esfuerzos cortos por encima del umbral, posición libre, recuperación igual al esfuerzo. Un bloque al 70 % en aero cierra la sesión. Todas las recuperaciones se hacen en posición aero: recuperar en aero enseña a tu cerebro a asociarla con el descanso (aunque, físicamente, no lo sea del todo).", "it": "Sforzi brevi sopra la soglia, posizione libera, recupero pari allo sforzo. Un blocco al 70 % in aero chiude la sessione. Tutti i recuperi si fanno in posizione aero: recuperare in aero insegna al tuo cervello ad associarla al riposo (anche se, fisicamente, non lo è del tutto).", "de": "Kurze Belastungen über der Schwelle, freie Position, Erholung so lang wie die Belastung. Ein Block bei 70 % in Aeroposition schließt die Einheit ab. Jede Erholung erfolgt in Aeroposition: So lernt dein Gehirn, sie mit Ruhe zu verbinden (auch wenn sie körperlich keine echte Pause ist).", "nl": "Korte inspanningen boven de drempel, vrije houding, herstel even lang als de inspanning. Een blok op 70 % in aero sluit de sessie af. Elk herstel gebeurt in aerohouding: zo leert je brein die houding te koppelen aan rust (ook al is het fysiek niet helemaal rust).", "pt": "Esforços curtos acima do limiar, posição livre, recuperação igual ao esforço. Um bloco a 70 % em aero encerra a sessão. Todas as recuperações são feitas na posição aero: recuperar em aero ensina seu cérebro a associá-la ao descanso (mesmo que, fisicamente, não seja bem um descanso).", "ja": "閾値を超える短い努力、ポジション自由、回復は努力と同じ長さ。最後は70 %のエアロブロックで締めます。 回復はすべてエアロポジションで行います。エアロで回復することで、脳がこの姿勢を休息と結びつけます（体にとっては完全な休息ではありませんが）。", "tr": "Eşiğin üzerinde kısa eforlar, serbest pozisyon, eforla eşit toparlanma. Seansı %70''te bir aero blok kapatır. Tüm toparlanmalar aero pozisyonda yapılır: aero''da toparlanmak beynine bu pozisyonu dinlenmeyle ilişkilendirmeyi öğretir (fiziksel olarak tam bir dinlenme olmasa da)."}'::jsonb,
  'objectif', replace('{"fr": "Faire monter ta puissance critique et ta PMA", "en": "Raise your critical power and VO2max", "es": "Subir tu potencia crítica y tu VO2max", "it": "Alzare la tua potenza critica e il VO2max", "de": "Deine kritische Leistung und VO2max steigern", "nl": "Je kritisch vermogen en VO2max verhogen", "pt": "Aumentar sua potência crítica e seu VO2max", "ja": "クリティカルパワーとVO2maxを高める", "tr": "Kritik gücünü ve VO2max''ını yükselt"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w1s3_name', 'base_ftp_aero_4w_w2s3_name', 'base_ftp_aero_4w_w3s3_name', 'base_ftp_aero_4w_w4s3_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Sortie longue en endurance, le cœur du travail aérobie. Le bloc central est en aéro à 70 % FTP, sans interruption : cherche une position que tu peux tenir, pas la plus basse.", "en": "Long endurance ride, the core of aerobic work. The central block is aero at 70% FTP with no break: find a position you can hold, not the lowest one.", "es": "Salida larga de resistencia, el corazón del trabajo aeróbico. El bloque central es en aero al 70 % FTP sin pausa: busca una posición que puedas mantener, no la más baja.", "it": "Uscita lunga di resistenza, il cuore del lavoro aerobico. Il blocco centrale è in aero al 70 % FTP senza interruzioni: cerca una posizione che puoi tenere, non la più bassa.", "de": "Lange Ausdauerfahrt, der Kern der aeroben Arbeit. Der Mittelblock ist Aero bei 70 % FTP ohne Unterbrechung: Such eine Position, die du halten kannst, nicht die tiefste.", "nl": "Lange duurrit, de kern van het aerobe werk. Het middenblok is aero op 70 % FTP zonder onderbreking: zoek een houding die je kunt volhouden, niet de laagste.", "pt": "Treino longo de resistência, o coração do trabalho aeróbio. O bloco central é em aero a 70 % FTP sem pausa: procure uma posição que consiga manter, não a mais baixa.", "ja": "有酸素トレーニングの中心となるロングライド。中央ブロックは70 % FTPのエアロを途切れず：一番低い姿勢ではなく、維持できる姿勢を探して。", "tr": "Aerobik çalışmanın kalbi olan uzun dayanıklılık sürüşü. Orta blok ara vermeden %70 FTP''de aero: en alçak değil, koruyabileceğin bir pozisyon bul."}'::jsonb,
  'objectif', replace('{"fr": "Construire la base aérobie avec {aero} minutes d''aéro d''affilée", "en": "Build your aerobic base with {aero} minutes of aero in one go", "es": "Construir la base aeróbica con {aero} minutos seguidos en aero", "it": "Costruire la base aerobica con {aero} minuti di aero di fila", "de": "Die aerobe Basis aufbauen, mit {aero} Minuten Aero am Stück", "nl": "Je aerobe basis opbouwen met {aero} minuten aero aan één stuk", "pt": "Construir a base aeróbia com {aero} minutos seguidos em aero", "ja": "{aero}分連続のエアロで有酸素ベースを作る", "tr": "Aralıksız {aero} dakika aero ile aerobik temel oluştur"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w2s4_name', 'base_ftp_aero_4w_w3s4_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Semaine plus légère : le corps assimile les trois semaines de travail. Deux blocs sweet spot, puis 10 minutes en aéro à 70 %. Toutes les récupérations se font en position aéro : récupérer en aéro apprend à ton cerveau à l''associer au repos (même si, physiquement, ce n''en est pas tout à fait un).", "en": "Lighter week: your body absorbs three weeks of work. Two sweet spot blocks, then 10 minutes aero at 70%. Every recovery is done in the aero position: recovering in aero teaches your brain to link it with rest (even though, physically, it isn''t quite rest).", "es": "Semana más ligera: el cuerpo asimila tres semanas de trabajo. Dos bloques sweet spot y luego 10 minutos en aero al 70 %. Todas las recuperaciones se hacen en posición aero: recuperar en aero enseña a tu cerebro a asociarla con el descanso (aunque, físicamente, no lo sea del todo).", "it": "Settimana più leggera: il corpo assimila tre settimane di lavoro. Due blocchi sweet spot, poi 10 minuti in aero al 70 %. Tutti i recuperi si fanno in posizione aero: recuperare in aero insegna al tuo cervello ad associarla al riposo (anche se, fisicamente, non lo è del tutto).", "de": "Leichtere Woche: Der Körper verarbeitet drei Trainingswochen. Zwei Sweet-Spot-Blöcke, dann 10 Minuten Aero bei 70 %. Jede Erholung erfolgt in Aeroposition: So lernt dein Gehirn, sie mit Ruhe zu verbinden (auch wenn sie körperlich keine echte Pause ist).", "nl": "Lichtere week: je lichaam verwerkt drie weken training. Twee sweetspotblokken, daarna 10 minuten aero op 70 %. Elk herstel gebeurt in aerohouding: zo leert je brein die houding te koppelen aan rust (ook al is het fysiek niet helemaal rust).", "pt": "Semana mais leve: o corpo assimila três semanas de trabalho. Dois blocos sweet spot e depois 10 minutos em aero a 70 %. Todas as recuperações são feitas na posição aero: recuperar em aero ensina seu cérebro a associá-la ao descanso (mesmo que, fisicamente, não seja bem um descanso).", "ja": "軽めの週：3週間の負荷を体に吸収させます。スイートスポット2本の後、70 %でエアロ10分。 回復はすべてエアロポジションで行います。エアロで回復することで、脳がこの姿勢を休息と結びつけます（体にとっては完全な休息ではありませんが）。", "tr": "Daha hafif hafta: vücut üç haftalık çalışmayı özümser. İki sweet spot bloğu, ardından %70''te 10 dakika aero. Tüm toparlanmalar aero pozisyonda yapılır: aero''da toparlanmak beynine bu pozisyonu dinlenmeyle ilişkilendirmeyi öğretir (fiziksel olarak tam bir dinlenme olmasa da)."}'::jsonb,
  'objectif', replace('{"fr": "Entretenir la FTP en semaine d''assimilation", "en": "Maintain your FTP during the recovery week", "es": "Mantener la FTP en la semana de asimilación", "it": "Mantenere la FTP nella settimana di scarico", "de": "Die FTP in der Entlastungswoche erhalten", "nl": "Je FTP onderhouden in de herstelweek", "pt": "Manter a FTP na semana de assimilação", "ja": "回復週にFTPを維持する", "tr": "Toparlanma haftasında FTP''ni koru"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w4s1_name');

UPDATE public.training_sessions
SET translations_json = jsonb_set(translations_json, '{live_comments,base_ftp_aero_4w_lc_recup}', '{"fr": "Récup en aéro : reste sur les prolongateurs. Ton cerveau apprend que c''est une position de repos.", "en": "Recover in aero: stay on the extensions. Your brain learns this is a resting position.", "es": "Recupera en aero: sigue en los acoples. Tu cerebro aprende que es una posición de descanso.", "it": "Recupero in aero: resta sulle protesi. Il tuo cervello impara che è una posizione di riposo.", "de": "Erholung in Aero: Bleib auf dem Aufsatz. Dein Gehirn lernt, dass das eine Ruheposition ist.", "nl": "Herstel in aero: blijf op de opzetstukken. Je brein leert dat dit een rusthouding is.", "pt": "Recupere em aero: fique no clipe. Seu cérebro aprende que é uma posição de descanso.", "ja": "エアロで回復：エアロバーに乗ったまま。脳がこれを休息の姿勢だと学びます。", "tr": "Aero''da toparlan: uzatmalarda kal. Beynin bunun bir dinlenme pozisyonu olduğunu öğrenir."}'::jsonb)
WHERE name LIKE 'base_ftp_aero_4w\_w%' ESCAPE '\';

UPDATE public.training_plans
SET translations_json = jsonb_set(translations_json, '{description}',
  (SELECT jsonb_object_agg(k, to_jsonb(v || ' ' || (r ->> k)))
   FROM jsonb_each_text(translations_json -> 'description') AS d(k, v),
        (SELECT '{"fr": "Toutes les récupérations se font en position aéro : récupérer en aéro apprend à ton cerveau à l''associer au repos (même si, physiquement, ce n''en est pas tout à fait un).", "en": "Every recovery is done in the aero position: recovering in aero teaches your brain to link it with rest (even though, physically, it isn''t quite rest).", "es": "Todas las recuperaciones se hacen en posición aero: recuperar en aero enseña a tu cerebro a asociarla con el descanso (aunque, físicamente, no lo sea del todo).", "it": "Tutti i recuperi si fanno in posizione aero: recuperare in aero insegna al tuo cervello ad associarla al riposo (anche se, fisicamente, non lo è del tutto).", "de": "Jede Erholung erfolgt in Aeroposition: So lernt dein Gehirn, sie mit Ruhe zu verbinden (auch wenn sie körperlich keine echte Pause ist).", "nl": "Elk herstel gebeurt in aerohouding: zo leert je brein die houding te koppelen aan rust (ook al is het fysiek niet helemaal rust).", "pt": "Todas as recuperações são feitas na posição aero: recuperar em aero ensina seu cérebro a associá-la ao descanso (mesmo que, fisicamente, não seja bem um descanso).", "ja": "回復はすべてエアロポジションで行います。エアロで回復することで、脳がこの姿勢を休息と結びつけます（体にとっては完全な休息ではありませんが）。", "tr": "Tüm toparlanmalar aero pozisyonda yapılır: aero''da toparlanmak beynine bu pozisyonu dinlenmeyle ilişkilendirmeyi öğretir (fiziksel olarak tam bir dinlenme olmasa da)."}'::jsonb AS r) AS x))
WHERE name_key = 'base_ftp_aero_4w_name'
  AND translations_json -> 'description' ->> 'fr' NOT LIKE '%récupérations se font en position aéro%';

